public class Main {
    public static void main(String[] args) throws Exception {
        FastReader r = new FastReader();
        int n = r.nextInt();
        long[] a = new long[n], dp = new long[n];
        for (int i = 0; i < n; i++) a[i] = r.nextLong();
        int[] st = new int[n];
        int top = 0;
        long ans = 0;
        for (int i = 0; i < n; i++) {
            long v = a[i];
            while (top > 0 && a[st[top - 1]] - st[top - 1] >= v - i) top--;
            long len, prev;
            if (top > 0) { int j = st[top - 1]; len = i - j; prev = dp[j]; }
            else { len = Math.min(i + 1, v); prev = 0; }
            dp[i] = prev + len * (2 * v - len + 1) / 2;
            ans = Math.max(ans, dp[i]);
            st[top++] = i;
        }
        System.out.println(ans);
    }
}

final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

