	}
	st := make([]int, 0, n)
	ans := 0
	for i, v := range a {
		for len(st) > 0 && a[st[len(st)-1]]-st[len(st)-1] >= v-i {
			st = st[:len(st)-1]
		}
		var length, prev int
		if len(st) > 0 {
			j := st[len(st)-1]
			length, prev = i-j, dp[j]
		} else {
			length, prev = min(i+1, v), 0
		}
		dp[i] = prev + length*(2*v-length+1)/2
		ans = max(ans, dp[i])
		st = append(st, i)
	}
	fmt.Println(ans)
}

